document.querySelectorAll(".fmc-tab").forEach(function(btn){btn.addEventListener("click",function(){document.querySelectorAll(".fmc-tab").forEach(function(x){x.classList.toggle("is-active",x===btn)});document.querySelectorAll(".fmc-page").forEach(function(p){p.classList.toggle("is-active",p.dataset.page===btn.dataset.tab)})})});document.querySelector(".fmc-close").addEventListener("click",function(){document.querySelector(".fmc-card").style.display="none"});